    const daily=filterAdRows(rowsFor(state.adsDaily,days),adChannelFilter),dates=[...new Set(daily.map(x=>x.date))].sort(),byDate=d=>daily.filter(x=>x.date===d);chart('adsChart','bar',{labels:dates.map(dateRu),datasets:[{label:'Расход, ₽',data:dates.map(d=>sum(byDate(d),'spend')),backgroundColor:'rgba(91,92,246,.78)',borderRadius:6,borderSkipped:false,yAxisID:'y'},{label:'Конверсии',data:dates.map(d=>sum(byDate(d),'conversions')),type:'line',borderColor:'#ef6a4a',backgroundColor:'#ef6a4a',tension:.25,yAxisID:'y1'}]},{plugins:{legend:{display:true,position:'bottom'}},scales:{x:{grid:{display:false}},y:{beginAtZero:true},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false}}}});
