    const byChannel=[['Яндекс Директ',directRows,'direct'],['VK Реклама',vkRows,'vkads']];document.getElementById('adChannelCompare').innerHTML=byChannel.map(([ch,data,key])=>{const tt=adTotals(data),st=apiStatus.integrations?.[key]||{};return `<div class="compare-card ${data.length?'':'muted-card'}"><strong>${esc(ch)}</strong><span>${data.length?`Расход ${money.format(tt.spend)}`:'Статистика за период отсутствует'}</span><span>Клики ${data.length?fmt.format(tt.clicks):'—'}</span><span>Конверсии ${data.length?fmt.format(tt.conversions):'—'}</span><span>CPA ${data.length&&tt.cpa!==null?money.format(tt.cpa):'—'}</span>${st.message?`<small>${esc(truncate(st.message,150))}</small>`:''}</div>`}).join('');
