    document.getElementById('adsTable').innerHTML=rows.length?rows.map(x=>{const [sl,sc]=normalizedStatus(x.status);let comment='Стабильно';const purpose=campaignPurpose(x);if(sl==='Остановлена')comment='Историческая кампания';else if(purpose==='Продвижение Telegram'||purpose==='Продвижение Дзена'||purpose==='Продвижение MAX')comment='Оцениваем переходы, CTR, CPC и качество трафика';else if(sl==='Активна'&&x.spend>0&&x.conversions===0&&x.clicks>=10)comment='Расход без конверсий';else if(x.cpa&&t.cpa&&x.cpa>t.cpa*1.5)comment='CPA выше среднего';return `<tr><td>${esc(x.channel)}</td><td>${esc(x.name)}</td><td>${pill(purpose,'info')}</td><td>${pill(sl,sc)}</td><td>${fmt.format(x.impressions)}</td><td>${fmt.format(x.clicks)}</td><td>${x.impressions?pct(x.ctr):'—'}</td><td>${money.format(x.spend)}</td><td>${x.clicks?money.format(x.cpc):'—'}</td><td>${fmt.format(x.conversions)}</td><td>${x.clicks?pct(x.cvr):'—'}</td><td>${x.cpa!==null?money.format(x.cpa):'—'}</td><td>${x.bounceRate?pct(x.bounceRate):'—'}</td><td>${x.avgPageviews?x.avgPageviews.toFixed(2):'—'}</td><td>${esc(comment)}</td></tr>`}).join(''):'<tr><td colspan="15" class="empty-cell">По выбранному каналу кампаний нет. Карточки выше показывают состояние каждого рекламного контура отдельно.</td></tr>';
