  function renderEmail(){
    const days=rangeDays(),e=emailSummary(days),p=emailSummary(days,days);metricGrid('emailMetrics',[
      {title:'Рассылки',value:e?fmt.format(e.campaigns):'—',note:`за ${days} дней`}, {title:'Отправлено',value:e?fmt.format(e.sent):'—',note:'UniSender'}, {title:'Доставляемость',value:e?pct(e.delivery):'—',note:'доставлено / отправлено'}, {title:'Открываемость',value:e?pct(e.openRate):'—',delta:e&&p?relDelta(e.openRate,p.openRate):null,note:'уникальные открытия / доставленные'}, {title:'CTR',value:e?pct(e.ctr):'—',delta:e&&p?relDelta(e.ctr,p.ctr):null,note:'клики / доставленные'}, {title:'Клики среди открывших',value:e?pct(e.ctor):'—',note:'клики / открывшие'}, {title:'Отписки',value:e?pct(e.unsubRate,2):'—',note:'от доставленных'}, {title:'Спам',value:e?pct(e.spamRate,2):'—',note:'от доставленных'}]);
    const rows=rowsFor(state.email,days).sort((a,b)=>String(a.date).localeCompare(String(b.date)));chart('emailChart','bar',{labels:rows.map(x=>dateRu(x.date)),datasets:[{label:'Открытия',data:rows.map(x=>x.delivered?x.opened/x.delivered*100:0),backgroundColor:'rgba(101,88,245,.78)'},{label:'Клики',data:rows.map(x=>x.delivered?x.clicked/x.delivered*100:0),backgroundColor:'rgba(15,157,135,.78)'}]},{plugins:{legend:{display:true,position:'bottom'}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{callback:v=>`${v}%`}}}});
    document.getElementById('emailIssues').innerHTML=emailRecommendations(days).map(issueHtml).join('');
    const recent=lastThreeEmails(),recentGrid=document.getElementById('emailRecentGrid');if(recentGrid)recentGrid.innerHTML=recent.length?recent.map(x=>{const or=x.delivered?x.opened/x.delivered*100:0,ctr=x.delivered?x.clicked/x.delivered*100:0;return `<article class="recent-email-card"><span>${dateRu(x.date)}</span><strong>${esc(x.name)}</strong><div><b>${pct(or)}</b><small>открытия</small></div><div><b>${pct(ctr)}</b><small>клики</small></div><div><b>${fmt.format(x.delivered)}</b><small>доставлено</small></div></article>`}).join(''):'<div class="empty-state">Рассылок пока нет.</div>';
    const visible=rows.slice().reverse();for(const x of recent){if(!visible.some(v=>String(v.id)===String(x.id)))visible.push({...x,outsideRange:true});if(visible.length>=Math.max(rows.length,3))break;}
    const medCtr=median((state.email||[]).filter(x=>x.delivered).map(x=>x.clicked/x.delivered*100));document.getElementById('emailTable').innerHTML=visible.length?visible.map(x=>{const delivery=x.sent?x.delivered/x.sent*100:0,or=x.delivered?x.opened/x.delivered*100:0,ctr=x.delivered?x.clicked/x.delivered*100:0,ctor=x.opened?x.clicked/x.opened*100:0,unsub=x.delivered?x.unsub/x.delivered*100:0,spam=x.delivered?x.spam/x.delivered*100:0;let l='Норма',c='info';if(delivery<95||spam>.1){l='Проверить';c='bad'}else if(medCtr&&ctr>medCtr*1.4){l='Сильная';c='good'}return `<tr class="${x.outsideRange?'outside-range':''}"><td>${x.reportUrl?`<a href="${esc(x.reportUrl)}" target="_blank" rel="noopener">${esc(x.name)}</a>`:esc(x.name)}${x.outsideRange?' <span class="micro-tag">вне периода</span>':''}</td><td>${dateRu(x.date)}</td><td>${fmt.format(x.sent)}</td><td>${fmt.format(x.delivered)}</td><td>${pct(delivery)}</td><td>${pct(or)}</td><td>${pct(ctr)}</td><td>${pct(ctor)}</td><td>${pct(unsub,2)}</td><td>${pct(spam,2)}</td><td>${pill(l,c)}</td></tr>`}).join(''):'<tr><td colspan="11" class="empty-cell">Нет рассылок.</td></tr>';
    const names=Object.fromEntries((state.email||[]).map(x=>[String(x.id),x.name]));document.getElementById('emailLinksTable').innerHTML=(state.emailLinks||[]).slice(0,80).map(x=>`<tr><td class="url-cell"><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(shortUrl(x.url))}</a></td><td>${esc(names[String(x.campaignId)]||x.campaignId)}</td><td>${fmt.format(x.clicks)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-cell">Данные по ссылкам появятся после синхронизации UniSender.</td></tr>';
  }

  function autoTasks(){const days=rangeDays(),pack=insights(days),all=[...pack.issues,...businessRecommendations(days),...seoRecommendations(),...adsRecommendations(days),...socialContentInsights(days,socialPostRows(days),socialChannels(days)),...emailRecommendations(days)],seen=new Set(),tasks=[];for(const x of all){const title=x.action||x.title;if(!title||seen.has(title))continue;seen.add(title);tasks.push({id:`auto-${hash(title)}`,title,priority:x.level==='high'?'high':x.level==='medium'?'medium':'low',source:x.area||'Автоаналитика',reason:x.title});}return tasks.slice(0,30);}
  async function loadBusinessCandidates(showErrors=true){
    const select=document.getElementById('businessCandidateSelect'),help=document.getElementById('businessCandidateHelp');if(!select)return;
    select.disabled=true;select.innerHTML='<option value="">Загружаю доступные счётчики…</option>';if(help)help.textContent='';
    try{
      const r=await apiFetch('/api/ybusiness/candidates'),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Не удалось получить список профилей');
      const list=d.candidates||[];select.innerHTML=list.length?'<option value="">Выберите нужный профиль…</option>'+list.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(d.selectedCounterId)?'selected':''}>${esc(x.name)}${x.site?` · ${esc(x.site)}`:''} · счётчик ${esc(x.id)}</option>`).join(''):'<option value="">Подходящие счётчики не найдены</option>';
      document.getElementById('businessProfileUrlInput').value=d.profileUrl||state.meta?.ybusinessProfileUrl||'https://yandex.ru/sprav/173574593150/';
      if(help)help.innerHTML=list.length?`Найдено ${list.length} кандидатов. Выберите профиль, который относится к карточке <strong>173574593150</strong>. У каждого кандидата показано имя, сайт и ID счётчика.`:'Яндекс ID не вернул отдельный счётчик Бизнеса. Проверьте доступ к нужному профилю в Яндекс Бизнесе.';
    }catch(e){if(help)help.textContent=e.message||'Не удалось загрузить кандидатов';if(showErrors)showAlert(e.message||'Не удалось загрузить профили','error');}
    finally{select.disabled=false;}
  }
  async function saveBusinessProfile(e){
    e?.preventDefault();const counterId=document.getElementById('businessCandidateSelect')?.value||'',profileUrl=document.getElementById('businessProfileUrlInput')?.value.trim()||'';if(!counterId){showAlert('Выберите счётчик именно вашего профиля Яндекс Бизнеса.','error');return;}
    try{const r=await apiFetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({settings:{ybusiness_counter_id:counterId,ybusiness_profile_url:profileUrl}})}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Не удалось сохранить профиль');document.getElementById('businessProfileDialog').close();showAlert('Профиль сохранён. Загружаю его статистику…','success');await syncOne('ybusiness');}catch(ex){showAlert(ex.message||'Не удалось сохранить профиль','error');}
  }
  function renderBusiness(){
    const days=rangeDays(),c=businessSummary(days),p=businessSummary(days,days),d=(k)=>c&&p?relDelta(c[k],p[k]):null,sync=apiStatus.integrations?.ybusiness||{},profileUrl=state.meta?.ybusinessProfileUrl||'https://yandex.ru/sprav/173574593150/',counterId=state.meta?.ybusinessCounterId||'';
    const bound=document.getElementById('businessBoundProfile'),link=document.getElementById('businessProfileLink');if(bound)bound.textContent=counterId?`Счётчик ${counterId}`:'Выберите профиль один раз';if(link){link.href=profileUrl;link.textContent='Открыть карточку 173574593150';}
    metricGrid('businessMetrics',[
      {title:'Визиты в профиль',value:c?fmt.format(c.profileViews):'—',delta:d('profileViews'),note:'счётчик выбранного профиля'}, {title:'Посетители профиля',value:c?fmt.format(c.targetClients):'—',delta:d('targetClients'),note:'уникальные пользователи'}, {title:'Действия',value:c?fmt.format(c.targetActions):'—',delta:d('targetActions'),note:'доступные системные цели'}, {title:'Доля действий',value:c&&c.profileViews?pct(c.targetActions/c.profileViews*100):'—',note:'действия / визиты'}, {title:'Маршруты',value:c?fmt.format(c.routes):'—',delta:d('routes'),note:'построение маршрута'}, {title:'Звонки',value:c?fmt.format(c.calls):'—',delta:d('calls'),note:'клик на звонок'}, {title:'CTA / сайт',value:c?fmt.format(c.websiteClicks):'—',delta:d('websiteClicks'),note:'если цель доступна'}, {title:'Контент',value:c?fmt.format(c.photoViews):'—',delta:d('photoViews'),note:'просмотры контента'}]);
    const rows=rowsFor(state.businessDaily,days),labels=rows.map(x=>dateRu(x.date));chart('businessChart','line',{labels,datasets:[{label:'Визиты в профиль',data:rows.map(x=>num(x.profileViews)),borderColor:'#5b5cf6',backgroundColor:'rgba(91,92,246,.08)',fill:true,tension:.28},{label:'Действия',data:rows.map(x=>num(x.targetActions)),borderColor:'#12a594',tension:.28},{label:'Маршруты',data:rows.map(x=>num(x.routes)),borderColor:'#f17852',tension:.28}]},{plugins:{legend:{display:true,position:'bottom'}}});
    const insights=businessRecommendations(days);document.getElementById('businessInsights').innerHTML=insights.length?insights.map(issueHtml).join(''):'<div class="empty-state">Сигналов пока нет.</div>';
    document.getElementById('businessActions').innerHTML=c?[['Маршруты',c.routes],['Звонки',c.calls],['CTA / сайт',c.websiteClicks],['Контент',c.photoViews]].map(([n,v])=>`<div class="compare-card"><strong>${esc(n)}</strong><div class="compare-main">${fmt.format(v)}</div><span>за ${days} дней</span></div>`).join(''):`<div class="empty-state"><strong>Сначала привяжите правильный профиль</strong><span>${esc(sync.message||'Откройте настройку профиля и выберите его счётчик Метрики.')}</span></div>`;
    const q=(state.businessQueries||[]).slice(0,8),list=document.getElementById('businessSourceList');if(list)list.innerHTML=q.length?q.map((x,i)=>`<div class="rank-row"><span class="rank-num">${i+1}</span><span>${esc(ruLabel(x.query,'source'))}</span><strong>${fmt.format(x.visits)}</strong></div>`).join(''):`<div class="empty-state">Источники появятся, если выбранный счётчик Яндекс Бизнеса отдаёт этот разрез.</div>`;
    const ov=document.querySelector('#overview #businessOverview');if(ov)ov.innerHTML=c?`<div><span>Визиты</span><strong>${fmt.format(c.profileViews)}</strong></div><div><span>Действия</span><strong>${fmt.format(c.targetActions)}</strong></div><div><span>Маршруты</span><strong>${fmt.format(c.routes)}</strong></div><div><span>Звонки</span><strong>${fmt.format(c.calls)}</strong></div>`:`<div class="empty-state">Профиль Яндекс Бизнеса требует привязки.</div>`;
  }
  async function workspaceSave(item){const r=await apiFetch('/api/workspace/upsert',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Не удалось сохранить');return d;}
  async function workspaceRemove(id){const r=await apiFetch(`/api/workspace/item/${encodeURIComponent(id)}`,{method:'DELETE'});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||'Не удалось удалить');}}
  function workspaceBy(kind){return (state.workspace||[]).filter(x=>x.kind===kind);}
  function setWorkspaceTab(tab){
    document.querySelectorAll('.workspace-tab').forEach(b=>{const active=b.dataset.workspaceTab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');});
    document.querySelectorAll('[data-workspace-pane]').forEach(p=>{const active=p.dataset.workspacePane===tab;p.hidden=!active;p.classList.toggle('active',active);});
  }
  function renderTasks(){const items=autoTasks(),ord={high:0,medium:1,low:2};items.sort((a,b)=>ord[a.priority]-ord[b.priority]);document.getElementById('taskList').innerHTML=items.length?items.map(x=>`<div class="task-item"><button class="mini-add-btn" data-auto-kanban="${esc(x.id)}" title="В канбан">+</button><div><div class="task-title">${esc(x.title)}</div><div class="task-meta">${esc(x.source||'')} ${x.reason?`· ${esc(x.reason)}`:''}</div></div><span class="priority ${x.priority}">${x.priority==='high'?'Высокий':x.priority==='medium'?'Средний':'Низкий'}</span></div>`).join(''):'<div class="empty-state">Критичных задач по аналитике нет.</div>';document.getElementById('focusSteps').innerHTML=items.slice(0,6).map(x=>`<li>${esc(x.title)}</li>`).join('')||'<li>Критичных задач по доступным данным нет.</li>';document.querySelectorAll('[data-auto-kanban]').forEach(b=>b.addEventListener('click',()=>addAutoTaskToKanban(b.dataset.autoKanban)));renderWorkspace();}
  function renderWorkspace(){const cards=workspaceBy('kanban'),lists=workspaceBy('checklist'),checks=workspaceBy('checkitem'),notes=workspaceBy('note'),recs=autoTasks().slice(0,6);const rec=document.getElementById('workspaceRecommendations');if(rec)rec.innerHTML=recs.length?recs.map(x=>`<div class="issue-item"><div class="issue-icon ${x.priority==='high'?'high':x.priority==='medium'?'medium':'low'}">↗</div><div><div class="issue-title">${esc(x.reason||x.title)}</div><div class="issue-text">${esc(x.title)}</div><button class="link-btn ws-add-rec" data-auto="${esc(x.id)}">Добавить в канбан</button></div></div>`).join(''):'<div class="empty-state">По текущим данным срочных рекомендаций нет.</div>';
    document.querySelectorAll('.ws-add-rec').forEach(b=>b.addEventListener('click',()=>addAutoTaskToKanban(b.dataset.auto)));
    const open=cards.filter(x=>x.status!=='done').length,done=cards.filter(x=>x.status==='done').length,checked=checks.filter(x=>x.checked).length;document.getElementById('workspaceStats').innerHTML=`<div><strong>${open}</strong><span>карточек открыто</span></div><div><strong>${done}</strong><span>завершено</span></div><div><strong>${lists.length}</strong><span>чек-листов</span></div><div><strong>${notes.length}</strong><span>заметок</span></div><div><strong>${checked}/${checks.length}</strong><span>пунктов закрыто</span></div>`;
    const cols=[['backlog','Бэклог'],['week','На этой неделе'],['progress','В работе'],['waiting','Ждёт'],['done','Готово']];document.getElementById('kanbanBoard').innerHTML=cols.map(([id,label])=>{const a=cards.filter(x=>(x.status||'backlog')===id);return`<section class="kanban-col" data-col="${id}"><div class="kanban-col-head"><strong>${label}</strong><span>${a.length}</span></div><div class="kanban-stack">${a.map(kanbanCardHtml).join('')||'<div class="kanban-empty">Пусто</div>'}</div></section>`}).join('');
    document.querySelectorAll('.kanban-status').forEach(sel=>sel.addEventListener('change',async()=>{const x=cards.find(c=>c.id===sel.dataset.id);if(x){await workspaceSave({...x,status:sel.value});await loadData();}}));document.querySelectorAll('.kanban-edit').forEach(b=>b.addEventListener('click',()=>openTaskDialog(cards.find(x=>x.id===b.dataset.id))));document.querySelectorAll('.kanban-delete').forEach(b=>b.addEventListener('click',async()=>{if(confirm('Удалить карточку?')){await workspaceRemove(b.dataset.id);await loadData();}}));
    document.getElementById('checklistGrid').innerHTML=lists.length?lists.map(l=>checklistHtml(l,checks.filter(x=>x.parentId===l.id))).join(''):'<div class="empty-state">Создайте чек-лист или используйте готовый шаблон.</div>';document.querySelectorAll('.check-toggle').forEach(c=>c.addEventListener('change',async()=>{const x=checks.find(i=>i.id===c.dataset.id);if(x){await workspaceSave({...x,checked:c.checked});await loadData();}}));document.querySelectorAll('.add-checkitem').forEach(b=>b.addEventListener('click',()=>openCheckItemDialog(b.dataset.parent)));document.querySelectorAll('.delete-checklist').forEach(b=>b.addEventListener('click',async()=>{if(confirm('Удалить чек-лист вместе с пунктами?')){await workspaceRemove(b.dataset.id);await loadData();}}));document.querySelectorAll('.delete-checkitem').forEach(b=>b.addEventListener('click',async()=>{await workspaceRemove(b.dataset.id);await loadData();}));
    renderNotes(notes);
  }
  function kanbanCardHtml(x){const statuses=[['backlog','Бэклог'],['week','Неделя'],['progress','В работе'],['waiting','Ждёт'],['done','Готово']];return`<article class="kanban-card priority-border-${esc(x.priority)}"><div class="kanban-card-top"><span class="priority ${esc(x.priority)}">${x.priority==='high'?'Высокий':x.priority==='low'?'Низкий':'Средний'}</span><div class="card-actions"><button class="icon-mini kanban-edit" data-id="${esc(x.id)}" title="Редактировать">✎</button><button class="icon-mini kanban-delete" data-id="${esc(x.id)}" title="Удалить">×</button></div></div><strong>${esc(x.title)}</strong>${x.body?`<p>${esc(truncate(x.body,220))}</p>`:''}${x.dueDate?`<div class="due-date ${new Date(x.dueDate)<new Date()&&x.status!=='done'?'overdue':''}">до ${esc(dateRu(x.dueDate))}</div>`:''}<select class="select kanban-status" data-id="${esc(x.id)}">${statuses.map(([v,l])=>`<option value="${v}" ${x.status===v?'selected':''}>${l}</option>`).join('')}</select></article>`;}
  function checklistHtml(list,items){const done=items.filter(x=>x.checked).length,p=items.length?Math.round(done/items.length*100):0;return`<article class="checklist-card"><div class="checklist-head"><div><strong>${esc(list.title)}</strong><span>${done}/${items.length} · ${p}%</span></div><button class="icon-mini delete-checklist" data-id="${esc(list.id)}">×</button></div><div class="progress"><i style="width:${p}%"></i></div><div class="check-items">${items.map(x=>`<div class="check-row"><label><input type="checkbox" class="check-toggle" data-id="${esc(x.id)}" ${x.checked?'checked':''}/><span>${esc(x.title)}</span></label><button class="icon-mini delete-checkitem" data-id="${esc(x.id)}">×</button></div>`).join('')}</div><button class="link-btn add-checkitem" data-parent="${esc(list.id)}">+ Добавить пункт</button></article>`;}
  function renderNotes(notes){const query=(document.getElementById('noteSearch')?.value||'').trim().toLowerCase(),filtered=notes.filter(x=>!query||`${x.title} ${x.body}`.toLowerCase().includes(query)).sort((a,b)=>num(b.pinned)-num(a.pinned)||String(b.updatedAt).localeCompare(String(a.updatedAt)));document.getElementById('notesGrid').innerHTML=filtered.length?filtered.map(x=>`<article class="note-card ${x.pinned?'pinned':''}" data-note-id="${esc(x.id)}"><div class="note-top"><span>${x.pinned?'📌 ':''}${esc(dateTimeRu(x.updatedAt))}</span><button class="icon-mini note-delete" data-id="${esc(x.id)}">×</button></div><strong>${esc(x.title)}</strong><p>${esc(x.body||'')}</p></article>`).join(''):'<div class="empty-state">Заметок пока нет.</div>';document.querySelectorAll('.note-card').forEach(c=>c.addEventListener('click',e=>{if(e.target.closest('.note-delete'))return;openNoteDialog(notes.find(x=>x.id===c.dataset.noteId))}));document.querySelectorAll('.note-delete').forEach(b=>b.addEventListener('click',async()=>{if(confirm('Удалить заметку?')){await workspaceRemove(b.dataset.id);await loadData();}}));}
  function openTaskDialog(x=null){document.getElementById('taskEditId').value=x?.id||'';document.getElementById('taskTitleInput').value=x?.title||'';document.getElementById('taskBodyInput').value=x?.body||'';document.getElementById('taskStatusInput').value=x?.status||'backlog';document.getElementById('taskPriorityInput').value=x?.priority||'medium';document.getElementById('taskDueInput').value=x?.dueDate||'';document.getElementById('taskDialog').showModal();}
  function openCheckItemDialog(parent){document.getElementById('checkItemParentInput').value=parent;document.getElementById('checkItemTitleInput').value='';document.getElementById('checkItemDialog').showModal();}
  function openNoteDialog(x=null){document.getElementById('noteEditId').value=x?.id||'';document.getElementById('noteTitleInput').value=x?.title||'';document.getElementById('noteBodyInput').value=x?.body||'';document.getElementById('notePinnedInput').checked=Boolean(x?.pinned);document.getElementById('noteDialog').showModal();}
  async function addAutoTaskToKanban(id){const x=autoTasks().find(t=>t.id===id);if(!x)return;const existing=workspaceBy('kanban').some(c=>c.title===x.title);if(existing){showAlert('Такая рекомендация уже есть в канбане.');return;}await workspaceSave({id:`kanban-${Date.now()}-${hash(x.title)}`,kind:'kanban',title:x.title,body:x.reason||'',priority:x.priority,status:'backlog'});showAlert('Рекомендация добавлена в канбан.','success');await loadData();}
  async function pushRecommendationsToKanban(){for(const x of autoTasks().slice(0,8)){if(!workspaceBy('kanban').some(c=>c.title===x.title))await workspaceSave({id:`kanban-${Date.now()}-${hash(x.title)}`,kind:'kanban',title:x.title,body:x.reason||'',priority:x.priority,status:'backlog'});}showAlert('Текущие рекомендации добавлены в бэклог.','success');await loadData();}
  const checklistTemplates={weekly:['Проверить трафик и заявки за неделю','Проверить ошибки Вебмастера','Разобрать расходы и CPA рекламы','Посмотреть сильные/слабые публикации','Проверить UniSender и клики','Зафиксировать 3 действия на следующую неделю'],ads:['Проверить цель и UTM','Проверить посадочную страницу','Проверить лимиты бюджета','Проверить аудитории/фразы','Проверить креативы и маркировку','Через 3–7 дней зафиксировать промежуточный вывод'],seo:['Проверить индексацию','Проверить Fatal/Critical','Посмотреть запросы с падением','Посмотреть запросы 4–15 позиции','Проверить CTR сниппетов','Выбрать страницы для следующей итерации'],content:['Проверить цель публикации','Сформулировать хук','Проверить визуал','Добавить UTM в ссылку','Опубликовать','Через 24–72 часа записать результат']};
  async function createChecklistTemplate(key){const items=checklistTemplates[key];if(!items)return;const titles={weekly:'Еженедельный маркетинговый контроль',ads:'Запуск рекламной кампании',seo:'SEO-проверка',content:'Публикация контента'},id=`checklist-${Date.now()}-${key}`;await workspaceSave({id,kind:'checklist',title:titles[key],priority:'medium'});for(let i=0;i<items.length;i++)await workspaceSave({id:`checkitem-${Date.now()}-${key}-${i}`,kind:'checkitem',parentId:id,title:items[i],sortOrder:i});await loadData();}


  function reportData(days){const site=siteSummary(days),prev=siteSummary(days,days),seo=seoSummary(),ads=aggregateAds(days),social=socialSummary(days),email=emailSummary(days),business=businessSummary(days),pack=insights(days);return {generatedAt:new Date().toISOString(),days,range:{...selectedRange},score:marketingScore(days),site,sitePrevious:prev,business,seo,ads,adTotals:adTotals(ads),social,email,recentEmails:lastThreeEmails(),issues:pack.issues,positives:pack.positives,businessPlan:businessRecommendations(days),seoPlan:seoRecommendations(),adPlan:adsRecommendations(days),socialPlan:socialContentInsights(days,socialPostRows(days),socialChannels(days)),emailPlan:emailRecommendations(days),tasks:autoTasks(),comment:managerText(days),syncLog:state.syncLog};}
  function selectedSections(){return [...document.querySelectorAll('.reportCheck:checked')].map(x=>x.value);}
  function renderReports(){const days=rangeDays(),d=reportData(days),preview=[`<div class="preview-range"><span>Период</span><strong>${esc(rangeLabel())}</strong></div>`];preview.push(`<div class="preview-score"><strong>${d.score}/100</strong><span>Индекс маркетинга</span></div>`);if(d.site)preview.push(`<div class="preview-row"><span>Визиты</span><strong>${fmt.format(d.site.visits)}</strong></div><div class="preview-row"><span>Заявки</span><strong>${fmt.format(d.site.formSubmits)}</strong></div>`);if(d.business)preview.push(`<div class="preview-row"><span>Яндекс Карты — действия</span><strong>${fmt.format(d.business.targetActions)}</strong></div>`);if(d.seo)preview.push(`<div class="preview-row"><span>SEO клики</span><strong>${fmt.format(d.seo.clicks)}</strong></div>`);if(d.adTotals.spend)preview.push(`<div class="preview-row"><span>Расход рекламы</span><strong>${money.format(d.adTotals.spend)}</strong></div>`);preview.push(`<div class="preview-row"><span>Проблемы высокого приоритета</span><strong>${d.issues.filter(x=>x.level==='high').length}</strong></div>`);document.getElementById('reportPreview').innerHTML=preview.join('');document.getElementById('managerComment').innerHTML=d.comment.map(x=>`<p>${esc(x)}</p>`).join('')||'<div class="empty-state">Недостаточно данных.</div>';}
  function tableHtml(headers,rows){return `<table class="pdf-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`;}
  function buildReportHtml(){const days=rangeDays(),d=reportData(days),sel=selectedSections(),title=esc(document.getElementById('reportName').value||'Маркетинговый отчёт'),k=(l,v,n='')=>`<div class="pdf-kpi"><span>${esc(l)}</span><strong>${v}</strong><small>${esc(n)}</small></div>`;let h=`<div class="pdf-report"><div class="pdf-brand">CS Marketing by skayfall</div><h1>${title}</h1><div class="report-date">${rangeLabel()} · сформирован ${new Date().toLocaleString('ru-RU')}</div>`;
    if(sel.includes('summary')){h+=`<h2>Резюме</h2><div class="pdf-kpis">${k('Индекс маркетинга',`${d.score}/100`)}${k('Визиты',d.site?fmt.format(d.site.visits):'—')}${k('Заявки',d.site?fmt.format(d.site.formSubmits):'—')}${k('SEO-клики',d.seo?fmt.format(d.seo.clicks):'—')}${k('Расход рекламы',d.adTotals.spend?money.format(d.adTotals.spend):'—')}</div><div class="pdf-comment">${d.comment.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`;}
    if(sel.includes('site')&&d.site){const cr=d.site.visits?d.site.formSubmits/d.site.visits*100:0;h+=`<h2>Сайт</h2><div class="pdf-kpis">${k('Посетители',fmt.format(d.site.users))}${k('Отказы',pct(d.site.bounce))}${k('Глубина',d.site.depth.toFixed(2))}${k('Время',duration(d.site.duration))}${k('CR формы',pct(cr))}</div>`;const rows=(state.sources||[]).slice(0,8).map(x=>`<tr><td>${esc(ruLabel(x.name,'source'))}</td><td>${fmt.format(x.visits)}</td><td>${pct(x.bounce)}</td><td>${fmt.format(x.conversions)}</td></tr>`);h+=`<h3>Источники</h3>${tableHtml(['Источник','Визиты','Отказы','Цели'],rows)}`;}
    if(sel.includes('business')&&d.business){h+=`<h2>Яндекс Карты</h2><div class="pdf-kpis">${k('Визиты в профиль',fmt.format(d.business.profileViews))}${k('Посетители профиля',fmt.format(d.business.targetClients))}${k('Доступные действия',fmt.format(d.business.targetActions))}${k('Маршруты',fmt.format(d.business.routes))}${k('Звонки',fmt.format(d.business.calls))}${k('CTA / сайт',fmt.format(d.business.websiteClicks))}</div>`;const br=(state.businessQueries||[]).slice(0,8).map(x=>`<tr><td>${esc(ruLabel(x.query,'source'))}</td><td>${fmt.format(x.visits)}</td></tr>`);if(br.length)h+=`<h3>Источники визитов в профиль</h3>${tableHtml(['Источник','Визиты'],br)}`;}
    if(sel.includes('seo')&&d.seo){h+=`<h2>SEO</h2><div class="pdf-kpis">${k('Показы',fmt.format(d.seo.shows))}${k('Клики',fmt.format(d.seo.clicks))}${k('CTR',pct(d.seo.ctr))}${k('Позиция',d.seo.position?d.seo.position.toFixed(1):'—')}${k('В поиске',fmt.format(d.seo.searchablePages||0))}</div>`;const rows=(state.seo||[]).slice(0,10).map(q=>`<tr><td>${esc(q.query)}</td><td>${fmt.format(q.shows)}</td><td>${fmt.format(q.clicks)}</td><td>${pct(q.ctr)}</td><td>${q.position.toFixed(1)}</td><td>${q.delta>0?'+':''}${q.delta.toFixed(1)}</td></tr>`);h+=tableHtml(['Запрос','Показы','Клики','CTR','Позиция','Δ'],rows);}
    if(sel.includes('ads')){h+=`<h2>Реклама</h2><div class="pdf-kpis">${k('Расход',money.format(d.adTotals.spend))}${k('Клики',fmt.format(d.adTotals.clicks))}${k('CTR',pct(d.adTotals.ctr))}${k('Конверсии',fmt.format(d.adTotals.conversions))}${k('CPA',d.adTotals.cpa!==null?money.format(d.adTotals.cpa):'—')}</div>`;const rows=d.ads.slice(0,12).map(x=>`<tr><td>${esc(x.channel)}</td><td>${esc(x.name)}</td><td>${money.format(x.spend)}</td><td>${fmt.format(x.clicks)}</td><td>${fmt.format(x.conversions)}</td><td>${x.cpa!==null?money.format(x.cpa):'—'}</td></tr>`);h+=tableHtml(['Канал','Кампания','Расход','Клики','Конверсии','CPA'],rows);}
    if(sel.includes('social')&&d.social){h+=`<h2>Соцсети</h2><div class="pdf-kpis">${k('Каналы',fmt.format(d.social.channels))}${k('Публикации',fmt.format(d.social.posts))}${k('Просмотры',fmt.format(d.social.views))}${k('Взаимодействия',fmt.format(d.social.interactions))}${k('ER',pct(d.social.er))}</div>`;const sr=d.social.byChannel.map(x=>`<tr><td>${esc(x.channel)}</td><td>${fmt.format(x.posts)}</td><td>${fmt.format(x.views)}</td><td>${fmt.format(x.interactions)}</td><td>${fmt.format(Math.round(x.avgViews||0))}</td></tr>`);h+=tableHtml(['Канал','Публикации','Просмотры','Взаимодействия','Среднее / пост'],sr);const sp=socialPostRows(days).sort((a,b)=>b.index-a.index).slice(0,5).map(x=>`<tr><td>${esc(x.channel)}</td><td>${esc(truncate(x.title,70))}</td><td>${esc(x.topic)}</td><td>${fmt.format(x.views)}</td><td>${x.index.toFixed(0)}</td></tr>`);if(sp.length)h+=`<h3>Сильные публикации</h3>${tableHtml(['Канал','Публикация','Тема','Просмотры','Индекс'],sp)}`;}
    if(sel.includes('email')&&d.email){h+=`<h2>Email</h2><div class="pdf-kpis">${k('Рассылки за период',fmt.format(d.email.campaigns))}${k('Доставляемость',pct(d.email.delivery))}${k('Открытия',pct(d.email.openRate))}${k('CTR',pct(d.email.ctr))}${k('Клики среди открывших',pct(d.email.ctor))}</div>`;const er=(d.recentEmails||[]).slice(0,3).map(x=>{const delivery=x.sent?x.delivered/x.sent*100:0,or=x.delivered?x.opened/x.delivered*100:0,ctr=x.delivered?x.clicked/x.delivered*100:0;return `<tr><td>${esc(x.name)}</td><td>${dateRu(x.date)}</td><td>${fmt.format(x.sent)}</td><td>${pct(delivery)}</td><td>${pct(or)}</td><td>${pct(ctr)}</td></tr>`});if(er.length)h+=`<h3>Три последние рассылки</h3>${tableHtml(['Рассылка','Дата','Отправлено','Доставляемость','Открываемость','CTR'],er)}`;}
    if(sel.includes('plan')){const plan=[...d.issues,...d.businessPlan,...d.seoPlan,...d.adPlan,...d.socialPlan,...d.emailPlan].filter((x,i,a)=>a.findIndex(y=>y.title===x.title)===i).slice(0,12);h+=`<h2>План действий</h2><ol class="pdf-plan">${plan.map(x=>`<li><strong>${esc(x.title)}</strong><span>${esc(x.action||x.text)}</span></li>`).join('')}</ol>`;}
    return h+'</div>';
  }
  async function downloadPdf(){const box=document.getElementById('reportCanvas');box.innerHTML=buildReportHtml();if(window.html2pdf)await html2pdf().set({margin:[8,8,8,8],filename:`cs-marketing-${iso(new Date())}.pdf`,image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(box.firstElementChild).save();else window.print();}
  function downloadBlob(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);}
  function downloadComment(){const days=rangeDays(),text=managerText(days).join('\n\n');downloadBlob('\uFEFF'+text,`cs-marketing-comment-${iso(new Date())}.txt`,'text/plain;charset=utf-8');}
  function downloadJson(){const days=rangeDays();downloadBlob(JSON.stringify(reportData(days),null,2),`cs-marketing-${iso(new Date())}.json`,'application/json');}
  function downloadCsv(){const days=rangeDays(),d=reportData(days),rows=[['section','metric','value'],['site','visits',d.site?.visits??''],['site','users',d.site?.users??''],['site','forms',d.site?.formSubmits??''],['site','email_clicks',d.site?.emailClicks??''],['business','profile_views',d.business?.profileViews??''],['business','target_actions',d.business?.targetActions??''],['seo','shows',d.seo?.shows??''],['seo','clicks',d.seo?.clicks??''],['ads','spend',d.adTotals.spend],['ads','clicks',d.adTotals.clicks],['ads','conversions',d.adTotals.conversions],['social','views',d.social?.views??''],['social','posts',d.social?.posts??''],['email','open_rate',d.email?.openRate??''],['email','ctr',d.email?.ctr??'']];downloadBlob('\uFEFF'+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\n'),`cs-marketing-${iso(new Date())}.csv`,'text/csv;charset=utf-8');}

  const integrations=[
    ['metrika','Яндекс Метрика','Сайт: посещаемость, поведение, цели, UTM, поисковые фразы'],['webmaster','Яндекс Вебмастер','SEO: запросы, позиции, индексация, диагностика'],['ybusiness','Яндекс Бизнес / Карты','Автоматический счётчик профиля в Метрике: визиты, пользователи, звонки, маршруты и другие системные действия'],['direct','Яндекс Директ','Кампании, расходы, клики, конверсии, поведение после клика'],['vkads','VK Реклама (ads.vk.com)','Рекламный контур: кампании, расходы и статистика; access token обновляется автоматически'],['vksocial','VK — публичный контент','При каждом обновлении приложение проверяет https://vk.ru/centr_santechniki; API сообщества используется только как дополнительный источник'],['telegram','Telegram — публичный контент','При каждом обновлении проверяется https://t.me/CS_trade_official и сохраняются названия постов и доступные просмотры'],['maxsocial','MAX — публичный контент','При каждом обновлении проверяется https://max.ru/id7724208038_biz; Bot API используется дополнительно, если настроен'],['dzen','Дзен — публичный контент','При каждом обновлении проверяется https://dzen.ru/centr_santehniki и сохраняются доступные метрики публикаций'],['unisender','UniSender','Рассылки, доставляемость, открытия, клики и ссылки']
  ];
  function renderIntegrations(){const grid=document.getElementById('integrationGrid');if(!grid)return;grid.innerHTML=integrations.map(([id,name,desc])=>{const s=apiStatus.integrations?.[id]||{},ok=Boolean(s.configured??s.connected),cls=!ok?'warn':s.status==='error'?'bad':s.status==='partial'||s.status==='pending'?'warn':'good',label=!ok?'Нужны доступы':s.status?statusLabel(s.status):'Доступы есть';return `<article class="integration-card"><div class="integration-title"><strong>${name}</strong>${pill(label,cls)}</div><p>${esc(desc)}</p><div class="integration-meta">${s.lastSync?`Последняя синхронизация: ${esc(dateTimeRu(s.lastSync))}`:'Синхронизация ещё не выполнялась'}${s.message?`<br>${esc(s.message)}`:''}${s.missing?.length?`<br>Не хватает: ${s.missing.map(esc).join(', ')}`:''}</div><button class="secondary-btn sync-one" data-source="${id}" ${ok?'':'disabled'}>Синхронизировать</button></article>`}).join('');grid.querySelectorAll('.sync-one').forEach(b=>b.addEventListener('click',()=>syncOne(b.dataset.source)));
    const required=[['ADMIN_PASSWORD','Secret','авторизация'],['ADMIN_USERNAME','Text','логин'],['SESSION_SECRET','Secret','сессия'],['SITE_URL','Text','поиск счётчика/хоста'],['YANDEX_TOKEN','Secret','Метрика + Вебмастер + Директ'],['UNISENDER_API_KEY','Secret','UniSender'],['VK_ADS_CLIENT_ID','Text','VK Реклама OAuth'],['VK_ADS_CLIENT_SECRET','Secret','VK Реклама OAuth']];
    const optional=[['VK_COMMUNITY_TOKEN','Secret','опционально: расширенная статистика VK-сообщества'],['TELEGRAM_CHANNEL_URL','Text','опционально: другой публичный Telegram URL'],['MAX_BOT_TOKEN','Secret','опционально: расширение MAX через Bot API'],['MAX_CHANNEL_ID','Text','опционально: ID канала MAX для Bot API'],['VK_SERVICE_TOKEN','Secret','read-токен VK для wall.get; основной вариант для автоматической загрузки постов'],['VK_CLIENT_TOKEN','Secret','альтернативное имя read-токена VK; приложение поддерживает его наравне с VK_SERVICE_TOKEN'],['VK_APP_ID','Text','опционально: ID приложения VK; вместе с VK_APP_SECRET позволяет получать серверный токен автоматически'],['VK_APP_SECRET','Secret','опционально: защищённый ключ приложения VK'],['VK_USER_TOKEN','Secret','опционально: пользовательский read-token для постов VK'],['VK_COMMUNITY_URL','Text','опционально: публичная страница VK для резервного чтения постов'],['VK_GROUP_ID','Text','опционально: ID сообщества, если автоопределение не сработало']];
    const all=[...required,...optional];document.getElementById('credentialChecklist').innerHTML=all.map(([k,t,use])=>`<tr><td><code>${k}</code></td><td>${t}</td><td>${apiStatus.runtime?.[k]?pill('Есть','good'):pill(optional.some(x=>x[0]===k)?'Опционально':'Нет',optional.some(x=>x[0]===k)?'info':'bad')}</td><td>${esc(use)}</td></tr>`).join('');const missing=required.filter(([k])=>!apiStatus.runtime?.[k]).map(x=>x[0]);document.getElementById('runtimeSummary').innerHTML=missing.length?`Не хватает обязательных параметров: <strong>${missing.map(esc).join(', ')}</strong>`:'<strong>Все обязательные параметры текущей конфигурации присутствуют.</strong>';
    document.getElementById('syncLogTable').innerHTML=(state.syncLog||[]).length?(state.syncLog||[]).map(x=>`<tr><td>${esc(x.source)}</td><td>${esc(dateTimeRu(x.lastSync))}</td><td>${pill(statusLabel(x.status),x.status==='ok'?'good':x.status==='error'?'bad':'warn')}</td><td>${esc(x.message||'')}</td></tr>`).join(''):'<tr><td colspan="4" class="empty-cell">Журнал пока пуст.</td></tr>';renderHealth();}

  function renderAll(){renderOverview();renderSite();renderBusiness();renderSeo();renderAds();renderSocial();renderEmail();renderTasks();renderReports();renderIntegrations();}
  function navigate(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const copy={overview:['Обзор','Состояние сайта, обращения и то, как люди вас находят.'],site:['Сайт','Полная Метрика: поведение, источники, страницы, цели, UTM и поисковые фразы.'],business:['Яндекс Карты','Профиль компании: посещаемость, целевые действия, маршруты и запросы из Яндекс Бизнеса.'],seo:['SEO','Вебмастер: запросы, позиции, индексация, диагностика и план изменений.'],ads:['Реклама','Яндекс Директ и VK Реклама: деньги, качество трафика и результат.'],social:['Соцсети','VK, Telegram, MAX и Дзен: публикации, просмотры, темы, форматы и рекомендации по каждому посту.'],email:['Email','UniSender: доставляемость, открытия, клики, ссылки и качество рассылок.'],tasks:['Рабочее пространство','Канбан, чек-листы, заметки и рекомендации, связанные с реальной аналитикой.'],reports:['Отчёты','Сводный PDF, комментарий по данным и выгрузки для дальнейшего анализа.'],integrations:['Интеграции','Состояние API, runtime-параметры и журнал синхронизаций.']}[view];document.getElementById('pageTitle').textContent=copy[0];document.getElementById('pageSubtitle').textContent=copy[1];document.getElementById('sidebar').classList.remove('open');}
  function shortUrl(v){try{const u=new URL(v);return u.pathname==='/'?u.hostname:`${u.hostname}${u.pathname}`;}catch{return truncate(v,58)}}
  function truncate(s,n){const x=String(s||'');return x.length>n?`${x.slice(0,n-1)}…`:x;}
  function hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(36);}

